impl Drop for OriginalSourceEncodingOwner{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Source encoding owner retains unsettled original custody");if self.failure.is_none(){unsafe{std::mem::ManuallyDrop::drop(&mut self.failure)}}if self.issuer.is_none(){unsafe{std::mem::ManuallyDrop::drop(&mut self.issuer)}}if self.work_issuer.is_none(){unsafe{std::mem::ManuallyDrop::drop(&mut self.work_issuer)}}if self.construction_issuer.is_none(){unsafe{std::mem::ManuallyDrop::drop(&mut self.construction_issuer)}}}}
