  self.submitted=self.submitted.checked_add(progress)?;let mut source=self.source.borrow_mut();if !self.identity.matches(&source){return Err(encoding_refusal("Source construction changed its original caller"))}let admitted=progress.fits(grant);source.consume_retained(progress)?;if !admitted{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Source construction exceeded its quoted physical grant").with_retained_progress(progress))}Ok(())
