impl Drop for EncodingEffectReceipt<'_>{fn drop(&mut self){if !self.settled{let (_,receipt,provenance)=self.settle();if receipt.is_some()||provenance.is_some(){unsafe{*self.retained_failure=Some(SourceEncodingRetainedFailure{receipt,provenance})}}}}}
